"use strict";

let g_CameraTargetEnt = -1;
let g_CameraMoveTicking = false;
let g_LastMoveTime = 0;
let g_LockPitch = null;
let g_LockYaw = null;
let g_DragAnchorWorld = null;

const CAMERA_DEFAULT_PITCH_MIN = 38;
const CAMERA_DEFAULT_PITCH_MAX = 60;
const CAMERA_EDGE_MARGIN = 16;
const CAMERA_MOVE_TICK = 0.03;

function GetScreenSize() {
    let panel = $.GetContextPanel();
    if (panel && panel.actualwidth > 0 && panel.actualheight > 0) {
        return [panel.actualwidth, panel.actualheight];
    }
    if (GameUI.GetScreenSize) {
        return GameUI.GetScreenSize();
    }
    while (panel && (panel.actualwidth <= 0 || panel.actualheight <= 0)) {
        panel = panel.GetParent();
    }
    if (panel) {
        return [panel.actualwidth, panel.actualheight];
    }
    return [0, 0];
}

function GetMoveDir() {
    const cursor = GameUI.GetCursorPosition();
    if (!cursor || cursor.length < 2) {
        return [0, 0];
    }

    const screen = GetScreenSize();
    const width = screen[0] || 0;
    const height = screen[1] || 0;
    if (width <= 0 || height <= 0) {
        return [0, 0];
    }

    let dx = 0;
    let dy = 0;
    if (cursor[0] <= CAMERA_EDGE_MARGIN) {
        dx = -1;
    } else if (cursor[0] >= width - CAMERA_EDGE_MARGIN) {
        dx = 1;
    }

    if (cursor[1] <= CAMERA_EDGE_MARGIN) {
        dy = 1;
    } else if (cursor[1] >= height - CAMERA_EDGE_MARGIN) {
        dy = -1;
    }

    return [dx, dy];
}

function TickCameraMove() {
    if (g_CameraTargetEnt === -1) {
        g_CameraMoveTicking = false;
        return;
    }

    const now = Game.GetGameTime();
    const dt = g_LastMoveTime > 0 ? Math.max(now - g_LastMoveTime, 0) : CAMERA_MOVE_TICK;
    g_LastMoveTime = now;

    if (GameUI.IsMouseDown && GameUI.IsMouseDown(2)) {
        const cursor = GameUI.GetCursorPosition();
        if (cursor && cursor.length >= 2 && GameUI.GetScreenWorldPosition) {
            if (!g_DragAnchorWorld) {
                const anchor = GameUI.GetScreenWorldPosition(cursor[0], cursor[1]);
                if (!anchor) {
                    g_CameraMoveTicking = true;
                    $.Schedule(CAMERA_MOVE_TICK, TickCameraMove);
                    return;
                }
                g_DragAnchorWorld = anchor;
            }
            const currentWorld = GameUI.GetScreenWorldPosition(cursor[0], cursor[1]);
            if (g_DragAnchorWorld && currentWorld) {
                const moveDx = g_DragAnchorWorld[0] - currentWorld[0];
                const moveDy = g_DragAnchorWorld[1] - currentWorld[1];
                if (moveDx !== 0 || moveDy !== 0) {
                    GameEvents.SendCustomGameEventToServer("camera_move_input", {
                        dx: moveDx,
                        dy: moveDy,
                        dt: dt,
                        world: 1
                    });
                }
                g_CameraMoveTicking = true;
                $.Schedule(CAMERA_MOVE_TICK, TickCameraMove);
                return;
            }
        }
    }

    g_DragAnchorWorld = null;

    const dir = GetMoveDir();
    if (dir[0] !== 0 || dir[1] !== 0) {
        GameEvents.SendCustomGameEventToServer("camera_move_input", {
            dx: dir[0],
            dy: dir[1],
            dt: dt
        });
    }

    g_CameraMoveTicking = true;
    $.Schedule(CAMERA_MOVE_TICK, TickCameraMove);
}

function StartCameraMove() {
    if (g_CameraMoveTicking) {
        return;
    }
    g_LastMoveTime = 0;
    TickCameraMove();
}

function ApplyRotationLock() {
    if (g_LockPitch !== null) {
        GameUI.SetCameraPitchMin(g_LockPitch);
        GameUI.SetCameraPitchMax(g_LockPitch);
    }
    if (g_LockYaw !== null) {
        GameUI.SetCameraYaw(g_LockYaw);
    }
}

function OnCameraSetTarget(data) {
    const entindex = data && data.entindex !== undefined ? data.entindex : -1;
    g_CameraTargetEnt = entindex;
    if (entindex !== -1) {
        GameUI.SetCameraTarget(entindex);
        g_LockPitch = (data && data.pitch !== undefined) ? data.pitch : null;
        g_LockYaw = (data && data.yaw !== undefined) ? data.yaw : null;
        ApplyRotationLock();
        StartCameraMove();
    }
}

function OnCameraClearTarget(data) {
    g_CameraTargetEnt = -1;
    g_LockPitch = null;
    g_LockYaw = null;
    GameUI.SetCameraTarget(-1);
    if (data && data.reset_default) {
        GameUI.SetCameraPitchMin(CAMERA_DEFAULT_PITCH_MIN);
        GameUI.SetCameraPitchMax(CAMERA_DEFAULT_PITCH_MAX);
    }
}

(function () {
    GameEvents.Subscribe("camera_set_target", OnCameraSetTarget);
    GameEvents.Subscribe("camera_clear_target", OnCameraClearTarget);
})();

